import pandas as pd

def clean(df):
    df = df.copy()
    for col in ['species', 'island', 'sex']:
        if col in df.columns:
            df[col] = df[col].astype('string').str.strip()
    if 'island' in df.columns:
        df['island'] = df['island'].replace({'Torgerson': 'Torgersen', 'Bisco': 'Biscoe'})
    if 'sex' in df.columns:
        df['sex'] = df['sex'].str.lower()
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(
            df['body_mass_g'].astype('string').str.replace(',', '', regex=False).str.strip(),
            errors='coerce'
        )
    df = df.drop_duplicates()
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'body_mass_g'])
    totals = d.groupby('species', dropna=True)['body_mass_g'].sum()
    return {str(k): float(v) for k, v in totals.items()}
